 const byName=n=>nodes.find(x=>x.name===n);
 /* spare magazines parked offscreen are not part of the gun's size or its anchors */
 nodes.forEach(g=>{if(/offscreen|off camera/i.test(g.name))g.userData.offscreen=true});
 const b=nodes[L.root];root.add(b);
